# More pages for HOW BIG IS IT? (see sizes.inc): real numbers from Earth, space, maths and guesses about the whole universe.
# Each: (title, line 1, line 2, value, about). value is an int, or a function that returns the digits as a string (the giants).
# about=1 means it is an estimate: the game says ABOUT. The digits go into facts.bin (packed, two to a byte) and are read from ROM.
# The pages are sorted in with the game's own numbers, smallest first (OLD has the size of each of those, from the game itself).
import math, decimal
from decimal import Decimal
def A(m, e): return int(Decimal(str(m)).scaleb(e))
def P10(e): return lambda: "1" + "0" * e
def POW2(e, minus=0):
    def f():
        c = decimal.Context(prec=int(e * 0.30103) + 20, Emax=decimal.MAX_EMAX, traps=[])
        return str(c.subtract(c.power(Decimal(2), e), Decimal(minus))) if minus else str(c.power(Decimal(2), e))
    return f
def fib(n):
    a, b = 0, 1
    for _ in range(n): a, b = b, a + b
    return a
MILLION_E = math.ceil(999999 / math.log10(2))   # the smallest power of 2 with a million digits

